const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),z=require('node:zlib'),E=require('../place-evidence.js'),P=require('../place-photos.js'),C=require('../place-conditions.js');const dir='docs/nationwide-expansion-20261020e/',load=n=>JSON.parse(z.gunzipSync(fs.readFileSync(dir+n+'.json.gz'))),m=load('manifest'),proof=load('source-evidence'),photos=load('selected-photos');
test('six additional places bind exact source identities to licensed real photographs and preserve partial-access conditions',()=>{assert.equal(m.facilities.length,6);assert.equal(m.courses.length,0);assert.equal(photos.length,6);assert.equal(new Set(photos.map(p=>p.photo.sha256)).size,6);let commons=0;for(const row of m.facilities){const s=proof.find(s=>s.row.id===row.id),p=photos.find(p=>p.id===row.id);assert.equal(row.name,s.tour.title.trim());assert.equal(row.lat,Number(s.tour.yCoord));assert.equal(row.lng,Number(s.tour.xCoord));assert(row.lat>=33&&row.lat<=39&&row.lng>=124&&row.lng<=132);assert.equal(P.get(row).sha256,p.photo.sha256);require('./helpers/photo-original.cjs')(p.photo);require('./helpers/place-photo-source.cjs')(p.photo);assert(p.photo.noCrop);if(p.photo.photoKind==='commons-photo'){commons++;assert(p.photo.commonsProof.imageinfo[0].extmetadata.Credit.value.includes('Own work'));assert(p.photo.dateNote.includes('2017')||p.photo.dateNote.includes('2023'));}else{assert(['Type1','Type3'].includes(p.photo.rightsType));assert.equal(p.photo.rightsType,p.officialImage.cpyrhtDivCd);}if(s.pet){assert.deepEqual(E.conditions(row),s.pet);assert.equal(s.pet.acmpyTypeCd,'일부구역 동반가능');}else assert.equal(E.get(row).introAllowance.wholeAreaConfirmed,false);assert.equal(E.conditions({...row,description:'changed'}),null);assert.equal(E.intro({...row,address:'unrelated branch'}),null);const html=fs.readFileSync('places/'+row.id+'/index.html','utf8');assert(html.includes(P.url(p.photo)));assert(!html.includes('undefined'));}assert.equal(commons,2);});
test('camping-only permission, barefoot path exclusion, room restrictions and same-name different-city identity remain explicit',()=>{const row=n=>m.facilities.find(r=>r.name.includes(n)),camp=row('학마을');assert.equal(camp.category,'캠핑');assert(camp.description.includes('펜션 동반 불가'));assert(C.panel(camp).includes('펜션 이용 시 반려동물동반은 금지'));assert(C.get(camp)[1].value.includes('중형견'));assert(C.get(camp)[2].value.includes('리드줄'));assert(C.panel(row('황성공원')).includes('맨발 걷기 황토길은 반려견 출입 불가'));assert(C.panel(row('알펜시아')).includes('지정된 반려견 동반 투숙 객실 외'));const bam=row('밤골');assert(bam.address.startsWith('경기도 용인시'));assert(bam.lat<37.3&&bam.lng>127.2);assert(C.get(row('차이나타운'))[1].value.includes('24kg 이하'));assert(C.get(row('올림픽공원'))[0].value.includes('실내 시설은 동반이 제한'));});
